package com.tamarasdk

import android.app.Activity
import android.content.Intent
import android.os.Handler
import android.os.Looper
import android.widget.Toast
import com.facebook.react.bridge.BaseActivityEventListener
import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReactContextBaseJavaModule
import com.facebook.react.bridge.ReactMethod
import com.google.gson.Gson

class TamaraSdkModule(reactContext: ReactApplicationContext) :
    ReactContextBaseJavaModule(reactContext), Tamara {

    private var _promise: Promise? = null

    private val activityEventListener =
        object : BaseActivityEventListener() {
            override fun onActivityResult(
                activity: Activity?,
                requestCode: Int,
                resultCode: Int,
                data: Intent?
            ) {
                when (requestCode) {
                    TamaraPayment.REQUEST_TAMARA_PAYMENT -> {
                        if (
                            TamaraPaymentHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraPaymentHelper.getData(data!!)
                            when (result?.status) {
                                PaymentResult.STATUS_CANCEL -> {
                                    _promise?.resolve("Payment canceled")
                                    Toast.makeText(activity, "Payment canceled", Toast.LENGTH_LONG)
                                        .show()
                                }
                                PaymentResult.STATUS_FAILURE -> {
                                    _promise?.resolve(result.getMessage() ?: "Payment error")
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Payment error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                }
                                PaymentResult.STATUS_SUCCESS -> {
                                    val checkout = TamaraPaymentHelper.checkOutSession(data)
                                    _promise?.resolve(Gson().toJson(checkout))
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_ORDER_DETAIL -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    _promise?.resolve(result.getMessage() ?: "Order Detail error")
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val orderDetail =
                                        TamaraInformationHelper.getDataOrderDetail(data)
                                    _promise?.resolve(Gson().toJson(orderDetail))
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_CAPTURE_PAYMENT -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Capture Payment error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                    _promise?.resolve(
                                        result.getMessage() ?: "Capture Payment error"
                                    )
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val capturePayment =
                                        TamaraInformationHelper.getDataCapturePayment(data)
                                    _promise?.resolve(Gson().toJson(capturePayment))
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_REFUNDS -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Refunds error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                    _promise?.resolve(result.getMessage() ?: "Refunds error")
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val refunds = TamaraInformationHelper.getDataRefunds(data)
                                    _promise?.resolve(Gson().toJson(refunds))
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_REFERENCE -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Order Reference error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val orderReference =
                                        TamaraInformationHelper.getOrderReference(data)
                                    _promise?.resolve(Gson().toJson(orderReference))
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_CART_PAGE -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Cart page error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val cartPage = TamaraInformationHelper.getCartPage(data)
                                    _promise?.resolve(Gson().toJson(cartPage))
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_PRODUCT -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Product error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val product = TamaraInformationHelper.getProduct(data)
                                    _promise?.resolve(Gson().toJson(product))
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_CANCEL -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Cancel order error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val cancelOrder = TamaraInformationHelper.getCancelOrder(data)
                                    _promise?.resolve(Gson().toJson(cancelOrder))
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_AUTHORISE -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Authorise order error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val authorise = TamaraInformationHelper.getAuthoriseOrder(data)
                                    Handler(Looper.getMainLooper()).post {
                                        _promise?.resolve(Gson().toJson(authorise))
                                    }
                                }
                            }
                        }
                    }
                    TamaraPayment.REQUEST_TAMARA_PAYMENT_OPTIONS -> {
                        if (
                            TamaraInformationHelper.shouldHandleActivityResult(
                                requestCode,
                                resultCode,
                                data
                            )
                        ) {
                            var result = TamaraInformationHelper.getData(data!!)
                            when (result?.status) {
                                InformationResult.STATUS_FAILURE -> {
                                    Toast.makeText(
                                            activity,
                                            result.getMessage() ?: "Check payment availability error",
                                            Toast.LENGTH_LONG
                                        )
                                        .show()
                                }
                                InformationResult.STATUS_SUCCESS -> {
                                    val paymentOptions = TamaraInformationHelper.getPaymentOptions(data)
                                    Handler(Looper.getMainLooper()).post {
                                        _promise?.resolve(Gson().toJson(paymentOptions))
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

    init {
        reactContext.addActivityEventListener(activityEventListener)
    }

    override fun getName(): String {
        return "TamaraSdk"
    }

