        authToken: String,
        apiUrl: String,
        notificationWebHook: String,
        publishKey: String,
        notificationToken: String,
        isSandbox: Boolean,
        promise: Promise
    ) {
        _promise = promise
        init(
            authToken,
            apiUrl,
            notificationWebHook,
            publishKey,
            notificationToken,
            isSandbox
        )
    }

