    ////
    override fun init(
        authToken: String,
        apiUrl: String,
        notificationWebHook: String,
        publishKey: String,
        notificationToken: String,
        isSanbox: Boolean
    ) {
        TamaraPayment.initialize(
            authToken,
            apiUrl,
            notificationWebHook,
            publishKey,
            notificationToken,
            isSanbox
        )
    }

    override fun paymentCheckout(
        checkOutUrl: String,
        successCallbackUrl: String,
        failureCallbackUrl: String,
        cancelCallbackUrl: String
    ) {
        val activity = currentActivity ?: throw IllegalStateException("Current activity is null")
        TamaraPayment.startPayment(
            activity!!,
            checkOutUrl,
            successCallbackUrl,
            failureCallbackUrl,
            cancelCallbackUrl
        )
    }

    override fun getOrderDetail(orderId: String) {
        val activity = currentActivity ?: throw IllegalStateException("Current activity is null")
        TamaraPayment.getOrderDetail(activity!!, orderId)
    }

    override fun getCapturePayment(jsonData: String) {
        val activity = currentActivity ?: throw IllegalStateException("Current activity is null")
        TamaraPayment.getCapturePayment(activity!!, jsonData)
